import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.Nk14N-ai.js";const u=JSON.parse('{"title":"Chapter 13: Kinetic Simulation Sandbox","description":"","frontmatter":{},"headers":[],"relativePath":"kinetic_sim.md","filePath":"kinetic_sim.md"}'),n={name:"kinetic_sim.md"};function o(r,e,l,h,c,d){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="chapter-13-kinetic-simulation-sandbox" tabindex="-1">Chapter 13: Kinetic Simulation Sandbox <a class="header-anchor" href="#chapter-13-kinetic-simulation-sandbox" aria-label="Permalink to &quot;Chapter 13: Kinetic Simulation Sandbox&quot;">​</a></h1><p>This directory contains the full local simulation environment for <strong>Kinetic</strong>, a decentralized DNS and web hosting network built on Kademlia DHT. It orchestrates 50 autonomous nodes running inside isolated containers to test real-world network conditions, domain registration, and hosting failovers.</p><h2 id="_1-architecture-core-components" tabindex="-1">1. Architecture &amp; Core Components <a class="header-anchor" href="#_1-architecture-core-components" aria-label="Permalink to &quot;1. Architecture &amp; Core Components&quot;">​</a></h2><p>The simulation consists of the following structure:</p><ul><li><strong>10 DHT Nodes</strong> (<code>DHT-Node</code>): Form the backbone of the decentralized hash table for resolving domains.</li><li><strong>6 CDN Hosts</strong> (<code>CDN-Host</code>): Provide decentralized web hosting, negotiating capacity with users.</li><li><strong>34 User Daemons</strong> (<code>UserDaemon</code>): AI-driven client agents that register identities (KIDs), compute VDF proofs to claim domains, and publish websites.</li><li><strong>Orchestrator</strong> (<code>orchestrator.py</code>): The central Python controller that manages the simulation lifecycle across 9 distinct phases.</li><li><strong>Dashboard</strong> (<code>kinetic-dashboard/</code>): A real-time React/Vite dashboard visually representing the state of the network.</li></ul><h2 id="_2-our-tricks-how-the-simulation-works" tabindex="-1">2. &quot;Our Tricks&quot; (How the Simulation Works) <a class="header-anchor" href="#_2-our-tricks-how-the-simulation-works" aria-label="Permalink to &quot;2. &quot;Our Tricks&quot; (How the Simulation Works)&quot;">​</a></h2><p>Because we are simulating a massive decentralized blockchain-like system purely using local containers, we implemented a few clever tricks to make the simulation both realistic and reliable:</p><ol><li><strong>The Subprocess/Exec Bridge:</strong> Instead of relying on a fragile API between the Python orchestrator and the containers, the orchestrator directly executes the real <code>kinetic-cli</code> Rust binaries inside the containers using <code>podman exec</code>. This guarantees that the network operates exactly as it would in production.</li><li><strong>The <code>jackpot.kin</code> Conflict Lock:</strong> To test the network&#39;s resilience to naming conflicts, Daemons #1 and #2 both attempt to register the highly coveted domain <code>jackpot.kin</code> simultaneously. Because our local Kademlia DHT doesn&#39;t inherently enforce VDF (Verifiable Delay Function) consensus rules by itself, the last writer would normally overwrite the first. To accurately simulate a real blockchain consensus rejection, we implemented a strict python lock (<code>_jackpot_winner_lock</code>) in <code>daemon_agent.py</code>. The first daemon to successfully verify their domain secures the lock, explicitly forcing the slower daemon into a <code>conflict_lost</code> state.</li><li><strong>Seamless Failover &amp; Auto-Retry:</strong> When a daemon detects it lost a conflict, it automatically falls back to its own name prefix (e.g., <code>bob.kin</code>), negotiates with its host to rename its web directory so no files are lost, and immediately retries the registration process.</li><li><strong>AI Personas (Ollama):</strong> We inject an element of human realism by assigning each daemon a persona (e.g., &quot;Alice — Startup Founder&quot;, &quot;Bob — Privacy Advocate&quot;). Between technical CLI executions, we query a local Ollama model to generate contextual, one-sentence thoughts about what they are doing, bringing the simulation to life on the dashboard.</li></ol><h2 id="_3-how-to-run-the-simulation" tabindex="-1">3. How to Run the Simulation <a class="header-anchor" href="#_3-how-to-run-the-simulation" aria-label="Permalink to &quot;3. How to Run the Simulation&quot;">​</a></h2><p>The simulation is located in the <code>kinetic-sim/</code> directory.</p><h3 id="pre-flight-setup-build" tabindex="-1">Pre-flight Setup &amp; Build <a class="header-anchor" href="#pre-flight-setup-build" aria-label="Permalink to &quot;Pre-flight Setup &amp; Build&quot;">​</a></h3><p>Generate the simulation keys and deploy the containerlab topology:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ensure you are in the kinetic-sim directory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup_sim.py</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the images and deploy the 50 containers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./deploy.sh</span></span></code></pre></div><h3 id="start-the-orchestrator" tabindex="-1">Start the Orchestrator <a class="header-anchor" href="#start-the-orchestrator" aria-label="Permalink to &quot;Start the Orchestrator&quot;">​</a></h3><p>Launch the brain of the simulation. This will boot the nodes and start the lifecycle phases:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PYTHONPATH=&quot;/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.local/lib/python3.14/site-packages&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestrator.py</span></span></code></pre></div><h3 id="start-the-dashboard" tabindex="-1">Start the Dashboard <a class="header-anchor" href="#start-the-dashboard" aria-label="Permalink to &quot;Start the Dashboard&quot;">​</a></h3><p>In a separate terminal, launch the frontend to watch the simulation unfold:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kinetic-dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><h2 id="_4-teardown" tabindex="-1">4. Teardown <a class="header-anchor" href="#_4-teardown" aria-label="Permalink to &quot;4. Teardown&quot;">​</a></h2><p>When you are finished running the simulation, you can easily destroy the 50 containers and network topology by running:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> containerlab</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> destroy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topology.clab.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> podman</span></span></code></pre></div>`,22)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
